from __future__ import annotations; import json; from pathlib import Path; import yaml; from common.testing import lockfile_registry, preflight; REPO_ROOT = Path(__file__).resolve().parents[2]
def _write_lockfile(path: Path, packages: dict[str, dict[str, object]]) -> Path: path.parent.mkdir(parents=True, exist_ok=True); payload = {'name': 'test-fixture', 'lockfileVersion': 3, 'requires': True, 'packages': packages}; path.write_text(json.dumps(payload, indent=2) + '\n', encoding='utf-8'); return path
def test_real_repository_lockfiles_pass_registry_check() -> None:
    'AC-testing.preflight.1'; discovered = lockfile_registry.discover_lockfiles(REPO_ROOT); rel_paths = {p.relative_to(REPO_ROOT).as_posix() for p in discovered}; assert 'apps/frontend/package-lock.json' in rel_paths; assert lockfile_registry.violations(REPO_ROOT) == []; assert lockfile_registry.main(['--repo-root', str(REPO_ROOT)]) == 0; 'AC-testing.preflight.1'; 'AC-testing.preflight.1'
    for _m2_path in ('package-lock.json', 'apps/frontend/package-lock.json', '.opencode/package-lock.json', 'tools/check_lockfile_registry.py', 'common/testing/lockfile_registry.py'): _m2_names = {_m2_c.name for _m2_c in preflight.select_checks([_m2_path], tier='static')}; assert 'lockfile-registry' in _m2_names, f'{_m2_path} did not select lockfile-registry'
    _m2_workflow = yaml.safe_load((REPO_ROOT / '.github' / 'workflows' / 'ci.yml').read_text(encoding='utf-8')); _m2_lint_commands = '\n'.join((str(_m2_step.get('run', '')) for _m2_step in _m2_workflow['jobs']['lint']['steps'])); assert 'tools/check_lockfile_registry.py' in _m2_lint_commands
def test_clean_synthetic_lockfile_passes(tmp_path: Path) -> None: 'AC-testing.preflight.1'; lockfile = _write_lockfile(tmp_path / 'apps' / 'frontend' / 'package-lock.json', {'': {'name': 'frontend', 'version': '0.1.0'}, 'node_modules/next': {'version': '15.0.0', 'resolved': 'https://registry.npmjs.org/next/-/next-15.0.0.tgz'}, 'node_modules/react': {'version': '19.0.0', 'resolved': 'https://registry.npmjs.org/react/-/react-19.0.0.tgz'}}); assert lockfile_registry.scan_lockfile(lockfile, repo_root=tmp_path) == []; assert lockfile_registry.main(['--repo-root', str(tmp_path)]) == 0; 'AC-testing.preflight.1'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); 'AC-testing.preflight.1'; assert lockfile_registry.main(['--repo-root', str(_m1_tmp)]) == 1; _m1_bad_lock = _m1_tmp / 'package-lock.json'; _m1_bad_lock.write_text('{not-valid-json', encoding='utf-8'); assert lockfile_registry.main(['--repo-root', str(_m1_tmp)]) == 1; _m1_bad_lock.write_text('{}\n', encoding='utf-8'); assert lockfile_registry.main(['--repo-root', str(_m1_tmp)]) == 1; _m1_bad_lock.write_text('{"packages": {}}\n', encoding='utf-8'); assert lockfile_registry.main(['--repo-root', str(_m1_tmp)]) == 1; _write_lockfile(_m1_bad_lock, {'': {'name': 'frontend', 'version': '0.1.0'}}); assert lockfile_registry.main(['--repo-root', str(_m1_tmp)]) == 1
def test_private_mirror_registry_url_fails_and_lists_package(tmp_path: Path, capsys) -> None: 'AC-testing.preflight.1'; _write_lockfile(tmp_path / 'apps' / 'frontend' / 'package-lock.json', {'': {'name': 'frontend', 'version': '0.1.0'}, 'node_modules/clean-pkg': {'version': '1.0.0', 'resolved': 'https://registry.npmjs.org/clean-pkg/-/clean-pkg-1.0.0.tgz'}, 'node_modules/@private/mirror-pkg': {'version': '2.1.0', 'resolved': 'https://npm.shopee.io/@private/mirror-pkg/-/mirror-pkg-2.1.0.tgz'}, 'node_modules/corp-pkg': {'version': '3.0.0', 'resolved': 'https://registry-NonPublic.internal.example/corp-pkg/-/corp-pkg-3.0.0.tgz'}}); rc = lockfile_registry.main(['--repo-root', str(tmp_path)]); assert rc == 1; err = capsys.readouterr().err; assert 'apps/frontend/package-lock.json' in err; assert 'node_modules/@private/mirror-pkg' in err; assert 'https://npm.shopee.io/@private/mirror-pkg/-/mirror-pkg-2.1.0.tgz' in err; assert 'node_modules/corp-pkg' in err; assert 'https://registry-NonPublic.internal.example/corp-pkg/-/corp-pkg-3.0.0.tgz' in err
